(513432, 50400, 8643, '<td valign="top">This is a stunning photo - wish I understood it....</td>', 'This is a stunning photo - wish I understood it....', '2003-12-15 05:05:36.000000', NULL, 1),
(513434, 50737, 8643, '<td valign="top">Elegant, brilliant colouring, nice capture, nice soft background, good stop action.</td>', 'Elegant, brilliant colouring, nice capture, nice soft background, good stop action.', '2003-12-15 05:09:46.000000', NULL, 1),
(513435, 50761, 8643, '<td valign="top">Very tranquil - nice composition, colouring and lighting.</td>', 'Very tranquil - nice composition, colouring and lighting.', '2003-12-15 05:11:18.000000', NULL, 1),
(513436, 50829, 8643, '<td valign="top">Nice idea but I''m not sure about the hard shadow on the left.</td>', 'Nice idea but I''m not sure about the hard shadow on the left.', '2003-12-15 05:12:48.000000', NULL, 1),
(513449, 50892, 14401, '<td valign="top">Simply gorgeous!</td>', 'Simply gorgeous!', '2003-12-15 06:16:10.000000', NULL, 1),
(513450, 50428, 14401, '<td valign="top">Very cute!  Nice job.</td>', 'Very cute!  Nice job.', '2003-12-15 06:17:27.000000', NULL, 1),
(513452, 50428, 10084, '<td valign="top">Very nicely captured. Composition helps to tell a story and you want to know about. Looks good in b&amp;w.</td>', 'Very nicely captured. Composition helps to tell a story and you want to know about. Looks good in b&w.', '2003-12-15 06:48:45.000000', NULL, 1),
(513455, 50890, 10084, '<td valign="top">Very interesting composition. Even though the faucet seems to be missing pieces you know what it is. Contrast is excellently used to make a very graphic and crisp image. The highlight helps to make this shot pop out. Your eyes are lead from the top of the faucet to the droplet of water.</td>', 'Very interesting composition. Even though the faucet seems to be missing pieces you know what it is. Contrast is excellently used to make a very graphic and crisp image. The highlight helps to make this shot pop out. Your eyes are lead from the top of the faucet to the droplet of water.', '2003-12-15 06:50:55.000000', NULL, 1),
(513456, 50728, 14401, '<td valign="top">Artsy</td>', 'Artsy', '2003-12-15 06:51:36.000000', NULL, 1),
(513457, 50598, 10084, '<td valign="top">Great reflection of the tree. Beautifully captured blue hues from the sky. The diagonal view of the tree is very pleasing to the eye.  The leaf in the water looks almost like a little stick figure.</td>', 'Great reflection of the tree. Beautifully captured blue hues from the sky. The diagonal view of the tree is very pleasing to the eye.  The leaf in the water looks almost like a little stick figure.', '2003-12-15 06:52:29.000000', NULL, 1),
(513458, 50797, 10084, '<td valign="top">Very much a graphical picture. Unfortunately the horizontal lines are very painful to look at. The reflective lines from the vase is absolutely beautiful. Curves and the symetry of those lines are impressive.</td>', 'Very much a graphical picture. Unfortunately the horizontal lines are very painful to look at. The reflective lines from the vase is absolutely beautiful. Curves and the symetry of those lines are impressive.', '2003-12-15 06:55:47.000000', NULL, 1),
(513459, 50042, 14401, '<td valign="top">This is a really nice photo - I really like the contrast between the grapes and the snow.</td>', 'This is a really nice photo - I really like the contrast between the grapes and the snow.', '2003-12-15 06:56:25.000000', NULL, 1),
(513460, 50888, 10084, '<td valign="top">Very nice capture of a droplet of water. I''m glad you used a white border, it really helps to frame this shot beautifully.<br/> <br/>Highlights and shadows on the droplets are really nice. The contrast is perfect.</td>', 'Very nice capture of a droplet of water. I''m glad you used a white border, it really helps to frame this shot beautifully. Highlights and shadows on the droplets are really nice. The contrast is perfect.', '2003-12-15 06:57:18.000000', NULL, 1),
(513461, 50621, 14401, '<td valign="top">Focus could be just a bit sharper.   Nice idea.</td>', 'Focus could be just a bit sharper.   Nice idea.', '2003-12-15 06:58:16.000000', NULL, 1),
(513462, 50833, 10084, '<td valign="top">Very nice capture of a melting ice cube. Lighting is very impressive and helps to frame the cube very well. The vertical crop works in this shot.</td>', 'Very nice capture of a melting ice cube. Lighting is very impressive and helps to frame the cube very well. The vertical crop works in this shot.', '2003-12-15 06:58:35.000000', NULL, 1),
(513463, 50864, 14401, '<td valign="top">I can actually hear that plop!</td>', 'I can actually hear that plop!', '2003-12-15 06:58:53.000000', NULL, 1),
(513464, 50839, 10858, '<td valign="top">Okay, this is a cute goldfish, but as far as I remember, your main subject should have been the water, not the fish inside. A homogenic bluey background would have helped a much here, the fish gets lost among the yellows, browns... The photo is too busy for me this way.</td>', 'Okay, this is a cute goldfish, but as far as I remember, your main subject should have been the water, not the fish inside. A homogenic bluey background would have helped a much here, the fish gets lost among the yellows, browns... The photo is too busy for me this way.', '2003-12-15 07:01:13.000000', NULL, 1),
(513465, 50409, 10084, '<td valign="top">Very impressive shot of a winter sunset/sunrise. The snow in the composition really helps to give a sense of coldness and the sun gives a warming feeling. Your eyes are lead from the bottom right toward the bridge with the help of the bank of the river/bay/body of water.</td>', 'Very impressive shot of a winter sunset/sunrise. The snow in the composition really helps to give a sense of coldness and the sun gives a warming feeling. Your eyes are lead from the bottom right toward the bridge with the help of the bank of the river/bay/body of water.', '2003-12-15 07:01:34.000000', NULL, 1),
(513466, 50889, 14401, '<td valign="top">Lovely photo with interesting composition!</td>', 'Lovely photo with interesting composition!', '2003-12-15 07:02:06.000000', NULL, 1),
(513467, 50763, 14401, '<td valign="top">The colors, the composition - what''s not to like?  Great photo!</td>', 'The colors, the composition - what''s not to like?  Great photo!', '2003-12-15 07:03:11.000000', NULL, 1),
(513469, 50841, 10084, '<td valign="top">Beautiful scene. Colors are very nice. The composition would be easier on the eyes if cropped a bit more on the left side of the picture. The reeds seem to overwhelm the picture.</td>', 'Beautiful scene. Colors are very nice. The composition would be easier on the eyes if cropped a bit more on the left side of the picture. The reeds seem to overwhelm the picture.', '2003-12-15 07:05:40.000000', NULL, 1),
(513470, 50864, 10084, '<td valign="top">Very good still-motion shot. Composition is very pleasing to the eye. Great reflections in the water.</td>', 'Very good still-motion shot. Composition is very pleasing to the eye. Great reflections in the water.', '2003-12-15 07:06:55.000000', NULL, 1),
(513471, 50852, 13091, '<td valign="top">Wow!!  Very beautiful effect.  I love it! Good focus and extraordinary colors!  To me it''s a ribbon!<br/></td>', 'Wow!!  Very beautiful effect.  I love it! Good focus and extraordinary colors!  To me it''s a ribbon!', '2003-12-15 07:08:02.000000', NULL, 1),
(513472, 50896, 14401, '<td valign="top">Nice photo, but looks a bit oversaturated.  Is it from post processing?  If not, I''d tone down the brassiness a bit.</td>', 'Nice photo, but looks a bit oversaturated.  Is it from post processing?  If not, I''d tone down the brassiness a bit.', '2003-12-15 07:08:42.000000', NULL, 1),
(513473, 50892, 13091, '<td valign="top">So beautiful that it looks unreal.... Congratulation, nice shot!!</td>', 'So beautiful that it looks unreal.... Congratulation, nice shot!!', '2003-12-15 07:09:45.000000', NULL, 1),
(513474, 50746, 14401, '<td valign="top">Beautiful!  I can hear the water rushing over the rocks!</td>', 'Beautiful!  I can hear the water rushing over the rocks!', '2003-12-15 07:09:51.000000', NULL, 1),
(513475, 50845, 14401, '<td valign="top">Guess you didn''t do this with a sprinkler in your backyard, LOL!  Very nice composition and  contrast.  I like it!</td>', 'Guess you didn''t do this with a sprinkler in your backyard, LOL!  Very nice composition and  contrast.  I like it!', '2003-12-15 07:11:35.000000', NULL, 1),
(513476, 50846, 13091, '<td valign="top">Sorry.... Interesting effect but I can''t see this trick for a while...</td>', 'Sorry.... Interesting effect but I can''t see this trick for a while...', '2003-12-15 07:12:06.000000', NULL, 1),
(513477, 50813, 14401, '<td valign="top">Lovely pastoral-like waterscape.  Beautifully executed, nice exposure.</td>', 'Lovely pastoral-like waterscape.  Beautifully executed, nice exposure.', '2003-12-15 07:12:57.000000', NULL, 1),
(513478, 50884, 10858, '<td valign="top">Beautiful DOF, nice composition here, my only problem is that snow (water) is only in the background. Your composition leads my eyes to the goose, and this distracts me, because I would search for water and all I find for the first time is this bird.</td>', 'Beautiful DOF, nice composition here, my only problem is that snow (water) is only in the background. Your composition leads my eyes to the goose, and this distracts me, because I would search for water and all I find for the first time is this bird.', '2003-12-15 07:13:15.000000', NULL, 1),
(513479, 50549, 14401, '<td valign="top">The colors in this picture are really lovely.  I might have cropped it a little differently, but perhaps your way was best.</td>', 'The colors in this picture are really lovely.  I might have cropped it a little differently, but perhaps your way was best.', '2003-12-15 07:15:05.000000', NULL, 1),
(513480, 50436, 14401, '<td valign="top">The water is still as glass - nice shot.  Love the reflections.</td>', 'The water is still as glass - nice shot.  Love the reflections.', '2003-12-15 07:16:09.000000', NULL, 1),
(513481, 50873, 10084, '<td valign="top">Great still motion shot. Composition is done very well. I like that you decide to do this in b&amp;w. Contrast is very good.</td>', 'Great still motion shot. Composition is done very well. I like that you decide to do this in b&w. Contrast is very good.', '2003-12-15 07:16:48.000000', NULL, 1),
(513482, 50690, 10858, '<td valign="top">I wouldn''t associate to water if I weren''t told these are water bottles. The foreground is a bit dark for me, too. I like the red bottle in front of the window, but I still needed more water here.</td>', 'I wouldn''t associate to water if I weren''t told these are water bottles. The foreground is a bit dark for me, too. I like the red bottle in front of the window, but I still needed more water here.', '2003-12-15 07:17:09.000000', NULL, 1),
(513483, 50830, 10858, '<td valign="top">The photo is too purple-bluey for me and it mostly looks like a winter landscape. I am not sure I would associate to the water / snow here, anyway, it''s on the photo, but I would like to see a more effective way that brings it out.</td>', 'The photo is too purple-bluey for me and it mostly looks like a winter landscape. I am not sure I would associate to the water / snow here, anyway, it''s on the photo, but I would like to see a more effective way that brings it out.', '2003-12-15 07:18:59.000000', NULL, 1),
(513484, 50674, 10084, '<td valign="top">Very interesting location to shot. Composition is pretty good, but maybe a panoramic vertical shot in which more of the top and the bottom is shown to the view may have more of an impact.<br/> <br/>Currently the viewers eyes are lead from the bottom up. With more of the top showing your eyes would flow from the top down just like the water.</td>', 'Very interesting location to shot. Composition is pretty good, but maybe a panoramic vertical shot in which more of the top and the bottom is shown to the view may have more of an impact. Currently the viewers eyes are lead from the bottom up. With more of the top showing your eyes would flow from the top down just like the water.', '2003-12-15 07:19:24.000000', NULL, 1),
(513485, 50832, 14401, '<td valign="top">Very nice shot.</td>', 'Very nice shot.', '2003-12-15 07:19:52.000000', NULL, 1),
(513487, 50886, 10084, '<td valign="top">Composition is well done. Interesting and inventive shot. Clear liquid becoming red. Wondering what chemicals you used. <br/>Only thing I like are some stray highlights that are reflecting off the glass.</td>', 'Composition is well done. Interesting and inventive shot. Clear liquid becoming red. Wondering what chemicals you used. Only thing I like are some stray highlights that are reflecting off the glass.', '2003-12-15 07:21:36.000000', NULL, 1),
(513489, 50884, 14401, '<td valign="top">Hey Buddy, ya wanna buy a duck?  Sorry, couldn''t help myself!  Duck''s expression reminded me of that old joke.  Interesting composition, the duck is in perfect focus - would like the background to be a little more so.</td>', 'Hey Buddy, ya wanna buy a duck?  Sorry, couldn''t help myself!  Duck''s expression reminded me of that old joke.  Interesting composition, the duck is in perfect focus - would like the background to be a little more so.', '2003-12-15 07:22:20.000000', NULL, 1),
(513490, 50871, 14401, '<td valign="top">pretty composition.  nice colors.</td>', 'pretty composition.  nice colors.', '2003-12-15 07:23:28.000000', NULL, 1),
(513491, 50065, 10084, '<td valign="top">Very impressive scenary. Composition is very well done. Your eyes are lead from the foreground to the background. Beautifully captured shadows reflecting off the water. That pole in the water helps to give an extra point of interest.</td>', 'Very impressive scenary. Composition is very well done. Your eyes are lead from the foreground to the background. Beautifully captured shadows reflecting off the water. That pole in the water helps to give an extra point of interest.', '2003-12-15 07:23:39.000000', NULL, 1),
(513492, 50900, 14401, '<td valign="top">Cool macro!  Now, how ya gonna top it for next week, LOL?</td>', 'Cool macro!  Now, how ya gonna top it for next week, LOL?', '2003-12-15 07:24:48.000000', NULL, 1),
(513493, 50846, 10858, '<td valign="top">Very nice abstract and I guess you spent a lot of time on the set up. B&amp;W works well here, anyway, water is not accented enough for my personal taste. I guess these are waterdrops, but for me the main subject is a Vasarely-like abstract painting when I look at this photo, and not the water itself, which I think should be more impostant.</td>', 'Very nice abstract and I guess you spent a lot of time on the set up. B&W works well here, anyway, water is not accented enough for my personal taste. I guess these are waterdrops, but for me the main subject is a Vasarely-like abstract painting when I look at this photo, and not the water itself, which I think should be more impostant.', '2003-12-15 07:25:24.000000', NULL, 1),
(513494, 50527, 10084, '<td valign="top">Beautiful colors coming from the oil in the water, it helps to show the flow of the water.I think maybe cropping the left side of the shot would help the composition.<br/> I think this is the most original non-setup shot of the challenge.</td>', 'Beautiful colors coming from the oil in the water, it helps to show the flow of the water.I think maybe cropping the left side of the shot would help the composition. I think this is the most original non-setup shot of the challenge.', '2003-12-15 07:27:03.000000', NULL, 1),
(513496, 50852, 10858, '<td valign="top">The photo is beautiful - colours, composition - but very few water here. I am in trouble when I have to vote, because as a flower photo, I love this very much! As water, well... as the main subject is the flower, I think water should be accented more.</td>', 'The photo is beautiful - colours, composition - but very few water here. I am in trouble when I have to vote, because as a flower photo, I love this very much! As water, well... as the main subject is the flower, I think water should be accented more.', '2003-12-15 07:28:33.000000', NULL, 1),
(513498, 50678, 14401, '<td valign="top">very nice!  good color, nice clarity.</td>', 'very nice!  good color, nice clarity.', '2003-12-15 07:30:29.000000', NULL, 1),
(513499, 50886, 14401, '<td valign="top">Very creative.  Nice shot.</td>', 'Very creative.  Nice shot.', '2003-12-15 07:32:26.000000', NULL, 1),
(513500, 50892, 10858, '<td valign="top">This is wonderful! B&amp;W was an excellent choice, and ice is water for sure, just a different aggregate. These shapes you caught here are amazing, just one little thing I could mention: I would have left equal space between the photo''s edges and the snowflace, because your subject is (almost) symmetric.</td>', 'This is wonderful! B&W was an excellent choice, and ice is water for sure, just a different aggregate. These shapes you caught here are amazing, just one little thing I could mention: I would have left equal space between the photo''s edges and the snowflace, because your subject is (almost) symmetric.', '2003-12-15 07:32:37.000000', NULL, 1),
(513503, 50847, 10084, '<td valign="top">The ribs of the water bottles really have a nice pattern. The air pocket give the composition an interesting point to focus on.</td>', 'The ribs of the water bottles really have a nice pattern. The air pocket give the composition an interesting point to focus on.', '2003-12-15 07:38:59.000000', NULL, 1),
(513505, 50872, 12802, '<td valign="top">Stunning, I love long exposure shots, this is a great example.  <br/> <br/>My only gripe is the snow covered grass in the front of the picture.  I''d have liked that not there.  (That''s only my opinion though...)<br/> <br/>A great shot. [10]</td>', 'Stunning, I love long exposure shots, this is a great example.   My only gripe is the snow covered grass in the front of the picture.  I''d have liked that not there.  (That''s only my opinion though...) A great shot. [10]', '2003-12-15 07:41:52.000000', NULL, 1),
(513510, 50631, 10858, '<td valign="top">Very nice sunset, and I like the waves coming to the coast. The sea could have got a bit more accent anyway, the sun''s colours playing on the water could be very effective here. Anyway, I like this photo! :-)</td>', 'Very nice sunset, and I like the waves coming to the coast. The sea could have got a bit more accent anyway, the sun''s colours playing on the water could be very effective here. Anyway, I like this photo! :-)', '2003-12-15 07:56:33.000000', NULL, 1),
(513511, 50793, 12802, '<td valign="top">A different take on the water challenge.  Wonder how many comments you get about it not being on topic...<br/> <br/>A really good shot, the colours of the clouds are amazing and the stars are also nice and clear.  8</td>', 'A different take on the water challenge.  Wonder how many comments you get about it not being on topic... A really good shot, the colours of the clouds are amazing and the stars are also nice and clear.  8', '2003-12-15 07:56:40.000000', NULL, 1),
(513512, 50900, 10858, '<td valign="top">Nice waterdrop, anyway I think more of them would be more effective. :-) May I have a guess? Is this a fork? :-)</td>', 'Nice waterdrop, anyway I think more of them would be more effective. :-) May I have a guess? Is this a fork? :-)', '2003-12-15 07:59:35.000000', NULL, 1),
(513515, 50833, 10858, '<td valign="top">The background is gorgeous as it goes from purple to black, your composition is excellent, I love the amount of negative space here. The ice seems like standing on a stage in highlight and it''s beautiful as it''s melting! Congrats and good luck. :-)</td>', 'The background is gorgeous as it goes from purple to black, your composition is excellent, I love the amount of negative space here. The ice seems like standing on a stage in highlight and it''s beautiful as it''s melting! Congrats and good luck. :-)', '2003-12-15 08:01:59.000000', NULL, 1),
(513516, 50855, 6532, '<td valign="top">Seems a bit cloudy and gray.  Lots of distractions.  I am assuming this is a fish tank - maybe to have put a solid complimentaryor neutral background on the tank would have helped.</td>', 'Seems a bit cloudy and gray.  Lots of distractions.  I am assuming this is a fish tank - maybe to have put a solid complimentaryor neutral background on the tank would have helped.', '2003-12-15 08:05:49.000000', NULL, 1),
(513517, 50895, 10084, '<td valign="top">Incredible focusing. Love the details in the feather. Very beautiful curves. Contrast of the shadows are really good and helps to bring out the subject. Wished that the droplets had more highlights or something to really make it pop out of the shot.</td>', 'Incredible focusing. Love the details in the feather. Very beautiful curves. Contrast of the shadows are really good and helps to bring out the subject. Wished that the droplets had more highlights or something to really make it pop out of the shot.', '2003-12-15 08:05:51.000000', NULL, 1),
(513518, 50813, 10858, '<td valign="top">Wonderful water scene, this is one of my favourites in this challenge. :-) Colours are amazing, composition is ecxellent: the fishers follow the rule of thirds very well, but they are small enough to leave very much space to your main subject, the water! Great job, good luck!</td>', 'Wonderful water scene, this is one of my favourites in this challenge. :-) Colours are amazing, composition is ecxellent: the fishers follow the rule of thirds very well, but they are small enough to leave very much space to your main subject, the water! Great job, good luck!', '2003-12-15 08:07:33.000000', NULL, 1),
(513519, 50621, 10084, '<td valign="top">Composition is pretty interesting. Lots of beautiful curves in the subjects. Great contrast in the glass. <br/>Wished that the light on the left side was a bit toned down. Kind of distracting from the subjects.</td>', 'Composition is pretty interesting. Lots of beautiful curves in the subjects. Great contrast in the glass. Wished that the light on the left side was a bit toned down. Kind of distracting from the subjects.', '2003-12-15 08:07:54.000000', NULL, 1),
(513520, 50722, 6532, '<td valign="top">Cool idea.  I am curious to know what the yellow thing is.  There appear to be spots on the waters surface.  Bubbles are a nice compliment.</td>', 'Cool idea.  I am curious to know what the yellow thing is.  There appear to be spots on the waters surface.  Bubbles are a nice compliment.', '2003-12-15 08:08:36.000000', NULL, 1),
(513521, 50732, 10858, '<td valign="top">I love the colours here, anyway I think focus is more on the fire than the water. The water doesn''t really have a character on the photo.</td>', 'I love the colours here, anyway I think focus is more on the fire than the water. The water doesn''t really have a character on the photo.', '2003-12-15 08:10:50.000000', NULL, 1),
(513522, 50842, 6532, '<td valign="top">I like this idea.  I think it would have been much more effective if the color of the sky could have been dipicted more in its true colors.  The absence of detail in the foreground is also a bit bothersome.</td>', 'I like this idea.  I think it would have been much more effective if the color of the sky could have been dipicted more in its true colors.  The absence of detail in the foreground is also a bit bothersome.', '2003-12-15 08:11:43.000000', NULL, 1),
(513523, 50818, 6532, '<td valign="top">WoW!  Great colors.  The details in the bubbles give this picture validity as a picture versus a painting.  Good job.  8</td>', 'WoW!  Great colors.  The details in the bubbles give this picture validity as a picture versus a painting.  Good job.  8', '2003-12-15 08:13:47.000000', NULL, 1),
(513524, 50592, 6532, '<td valign="top">Nice.  I like the creative and patriotic take on this otherwise old idea.  I think the light reflection on the blue bubble are distracting. Otherwise ....9</td>', 'Nice.  I like the creative and patriotic take on this otherwise old idea.  I think the light reflection on the blue bubble are distracting. Otherwise ....9', '2003-12-15 08:16:02.000000', NULL, 1),
(513525, 50900, 6532, '<td valign="top">Nice.  I am curious to know how you did this.  Is that a fork?</td>', 'Nice.  I am curious to know how you did this.  Is that a fork?', '2003-12-15 08:17:00.000000', NULL, 1),
(513526, 50561, 10858, '<td valign="top">A few weeks I would have probably asked you how this photo was done, now I have a guess. :-) I like the simplicity of colours very much, and the clarity of the water, too. It might be strange to hear this, but being the photo upside down gives it too much wow factor for my personal taste. :-) Don''t misunderstand me, I love the photo very much! I just wonder how my way of approaching photos change with time. Excellent work, and good luck. :-)</td>', 'A few weeks I would have probably asked you how this photo was done, now I have a guess. :-) I like the simplicity of colours very much, and the clarity of the water, too. It might be strange to hear this, but being the photo upside down gives it too much wow factor for my personal taste. :-) Don''t misunderstand me, I love the photo very much! I just wonder how my way of approaching photos change with time. Excellent work, and good luck. :-)', '2003-12-15 08:19:02.000000', NULL, 1),
(513527, 50555, 6532, '<td valign="top">I think you are trying to capture a mist coming off the water - if this is true I think a different angle - like more toward the water would have captured this better.  As it is the fog makes the picture look blurry - especially in the area of the sun glare.  Nice use of thirds.</td>', 'I think you are trying to capture a mist coming off the water - if this is true I think a different angle - like more toward the water would have captured this better.  As it is the fog makes the picture look blurry - especially in the area of the sun glare.  Nice use of thirds.', '2003-12-15 08:19:20.000000', NULL, 1),
(513528, 50860, 472, '<td valign="top">well, for starters, it''s nice and crisp and the lighting is good. and it''s clearly a boat. not sure how that ties in with the title.  i think you also may have overdone the photoshop. that might be hurting you here. also, the LMVs may vote you down for not actually showing water.</td>', 'well, for starters, it''s nice and crisp and the lighting is good. and it''s clearly a boat. not sure how that ties in with the title.  i think you also may have overdone the photoshop. that might be hurting you here. also, the LMVs may vote you down for not actually showing water.', '2003-12-15 08:19:27.000000', NULL, 1),
(513529, 50527, 6532, '<td valign="top">Enhancement of the colors would have worked nicely for this picture. A bit flat in color otherwise.  Good idea.</td>', 'Enhancement of the colors would have worked nicely for this picture. A bit flat in color otherwise.  Good idea.', '2003-12-15 08:20:34.000000', NULL, 1),
(513531, 50860, 10858, '<td valign="top">I am not sure I would reallize it''s under water without the title. Water could be more accented here, anyway the photo itself is very nice! :-)</td>', 'I am not sure I would reallize it''s under water without the title. Water could be more accented here, anyway the photo itself is very nice! :-)', '2003-12-15 08:23:21.000000', NULL, 1),
(513532, 50845, 6532, '<td valign="top">I was hoping there would a picture similiar to this.  Nice.  Brrrrr.....</td>', 'I was hoping there would a picture similiar to this.  Nice.  Brrrrr.....', '2003-12-15 08:23:41.000000', NULL, 1),
(513535, 50491, 6532, '<td valign="top">Did you try turning this upside down?  For me it would have been easier to visualize and perceive.  Great use of light.</td>', 'Did you try turning this upside down?  For me it would have been easier to visualize and perceive.  Great use of light.', '2003-12-15 08:25:56.000000', NULL, 1),
(513538, 50715, 6532, '<td valign="top">Nice.  Great contrasting colors.</td>', 'Nice.  Great contrasting colors.', '2003-12-15 08:26:34.000000', NULL, 1),
(513539, 50300, 10858, '<td valign="top">Unique idea, I like it. :-) Otherwise for me the main subject is the Whiskey, and water (ice) is just around to help it show up. Alltogether I like the photo itself and B&amp;W was an excellent choice.</td>', 'Unique idea, I like it. :-) Otherwise for me the main subject is the Whiskey, and water (ice) is just around to help it show up. Alltogether I like the photo itself and B&W was an excellent choice.', '2003-12-15 08:28:09.000000', NULL, 1),
(513540, 50797, 10858, '<td valign="top">Very nice abstract. :-) It was a good idea to fill the vase with water and manipulate the stripes this way. Anyway, for my personal taste, stripes get more accent than the water itself. B&amp;W was an excellent choice for this photo.</td>', 'Very nice abstract. :-) It was a good idea to fill the vase with water and manipulate the stripes this way. Anyway, for my personal taste, stripes get more accent than the water itself. B&W was an excellent choice for this photo.', '2003-12-15 08:28:37.000000', NULL, 1),
(513541, 50890, 6532, '<td valign="top">A bit to dark on the pipe between the faucet and the spout - absence of a connection.  This does not work for me.</td>', 'A bit to dark on the pipe between the faucet and the spout - absence of a connection.  This does not work for me.', '2003-12-15 08:28:52.000000', NULL, 1),
(513544, 50438, 472, '<td valign="top">this is way cool and atmospheric.</td>', 'this is way cool and atmospheric.', '2003-12-15 08:30:37.000000', NULL, 1),
(513545, 50567, 6532, '<td valign="top">Nice.  Good use of light.  Looks like a famous landscape photographer''s work - a compliment.</td>', 'Nice.  Good use of light.  Looks like a famous landscape photographer''s work - a compliment.', '2003-12-15 08:30:41.000000', NULL, 1),
(513546, 50725, 7086, '<td valign="top">Make a wish? OK, I wish it didn''t have that air bubble floating on the right. The colours appear too coppery/red but that is the drawback of editing on one system and displaying on another.</td>', 'Make a wish? OK, I wish it didn''t have that air bubble floating on the right. The colours appear too coppery/red but that is the drawback of editing on one system and displaying on another.', '2003-12-15 08:32:53.000000', NULL, 1),
(513547, 50087, 10887, '<td valign="top">Very beautiful. soft and nice.</td>', 'Very beautiful. soft and nice.', '2003-12-15 08:34:35.000000', NULL, 1),
(513548, 50378, 6532, '<td valign="top">Great capture.  I like the colors and the use of the fish in the background.  Good job.</td>', 'Great capture.  I like the colors and the use of the fish in the background.  Good job.', '2003-12-15 08:34:59.000000', NULL, 1),
(513549, 50678, 10887, '<td valign="top">Nice! Love the bubbles!</td>', 'Nice! Love the bubbles!', '2003-12-15 08:35:02.000000', NULL, 1),
(513551, 50673, 6532, '<td valign="top">Black and white works well here.</td>', 'Black and white works well here.', '2003-12-15 08:35:34.000000', NULL, 1),
(513553, 50888, 10887, '<td valign="top">Charming and simple. Bravo!</td>', 'Charming and simple. Bravo!', '2003-12-15 08:36:50.000000', NULL, 1),
(513554, 50879, 10887, '<td valign="top">Cute idea.</td>', 'Cute idea.', '2003-12-15 08:37:43.000000', NULL, 1),
(513556, 50734, 6532, '<td valign="top">A contrasting background would have worked nicely here.</td>', 'A contrasting background would have worked nicely here.', '2003-12-15 08:38:38.000000', NULL, 1),
(513557, 50576, 10084, '<td valign="top">Interesting that the sky almost completely blends in with the water. Almost no horizon. <br/>I think that the composition would benefit by cutting either some of the sky in the shot or cutting out the land. <br/>The thing sticking out of the water helps your eyes focus on it but then your eyes wander around not knowing what else to look at. It''s a bit too overwhelming.</td>', 'Interesting that the sky almost completely blends in with the water. Almost no horizon. I think that the composition would benefit by cutting either some of the sky in the shot or cutting out the land. The thing sticking out of the water helps your eyes focus on it but then your eyes wander around not knowing what else to look at. It''s a bit too overwhelming.', '2003-12-15 08:39:13.000000', NULL, 1);
INSERT INTO comments ("id", "image_id", "commenter_id", "raw_comment", "comment", "date", "edited", "made_during_challenge") VALUES
(513558, 50864, 10887, '<td valign="top">Nice!</td>', 'Nice!', '2003-12-15 08:39:16.000000', NULL, 1),
(513560, 50265, 10084, '<td valign="top">The diagonal shapes that the steps make is very interesting to the composition. Unfortunately the lighting is a bit bright and makes it tough to really see the water.</td>', 'The diagonal shapes that the steps make is very interesting to the composition. Unfortunately the lighting is a bit bright and makes it tough to really see the water.', '2003-12-15 08:41:49.000000', NULL, 1),
(513562, 50833, 10887, '<td valign="top">Nice to see that it started to melt a little, good work.</td>', 'Nice to see that it started to melt a little, good work.', '2003-12-15 08:42:43.000000', NULL, 1),
(513564, 50400, 10887, '<td valign="top">Just wonderful! Very well done!</td>', 'Just wonderful! Very well done!', '2003-12-15 08:43:13.000000', NULL, 1),
(513566, 50852, 10887, '<td valign="top">A wonderful shot full of life, great drops!</td>', 'A wonderful shot full of life, great drops!', '2003-12-15 08:44:18.000000', NULL, 1),
(513569, 50710, 6532, '<td valign="top">Appears to be out of focus...</td>', 'Appears to be out of focus...', '2003-12-15 08:46:19.000000', NULL, 1),
(513570, 50848, 10084, '<td valign="top">Very dynamic photo. Really shows motion in the shot. Great still motion. The diagonal composition of the shot leads your eyes from the right to the left .The color of the green apple gives you a good focus point to look at.</td>', 'Very dynamic photo. Really shows motion in the shot. Great still motion. The diagonal composition of the shot leads your eyes from the right to the left .The color of the green apple gives you a good focus point to look at.', '2003-12-15 08:47:28.000000', NULL, 1),
(513571, 50872, 10858, '<td valign="top">Wonderful! Although I wouldn''t have included the inner black border, I love this photo! This is so beautiful dynamic, I have the feeling it will break through my monitor! Great job, good luck! :-)</td>', 'Wonderful! Although I wouldn''t have included the inner black border, I love this photo! This is so beautiful dynamic, I have the feeling it will break through my monitor! Great job, good luck! :-)', '2003-12-15 08:48:28.000000', NULL, 1),
(513572, 50761, 10084, '<td valign="top">Very beautiful reflection in the water. The reflection seems to be too perfect. Sometime a little splash gives water an off some interesting shapes and reflective highlights.</td>', 'Very beautiful reflection in the water. The reflection seems to be too perfect. Sometime a little splash gives water an off some interesting shapes and reflective highlights.', '2003-12-15 08:50:55.000000', NULL, 1),
(513573, 50520, 10887, '<td valign="top">So beautiful.. love it!</td>', 'So beautiful.. love it!', '2003-12-15 08:51:25.000000', NULL, 1),
(513574, 50892, 10887, '<td valign="top">Wow! How did you do that?!</td>', 'Wow! How did you do that?!', '2003-12-15 08:52:13.000000', NULL, 1),
(513575, 50660, 10084, '<td valign="top">Contrast of the shadow is absolutely beautiful. Colors in the subject is very vivid and interesting. Reflections of the sky is also very nice.<br/>Only problem with this shot is that it crop seems to make the picture unbalanced. The water on the lower part seem to overwhelm the shot.</td>', 'Contrast of the shadow is absolutely beautiful. Colors in the subject is very vivid and interesting. Reflections of the sky is also very nice.Only problem with this shot is that it crop seems to make the picture unbalanced. The water on the lower part seem to overwhelm the shot.', '2003-12-15 08:54:46.000000', NULL, 1),
(513576, 50734, 10887, '<td valign="top">Cute idea and good shot!</td>', 'Cute idea and good shot!', '2003-12-15 08:59:38.000000', NULL, 1),
(513578, 50470, 9906, '<td valign="top">Why i s there a reflection of nothing?<br/>TC</td>', 'Why i s there a reflection of nothing?TC', '2003-12-15 09:01:37.000000', NULL, 1),
(513584, 50833, 10686, '<td valign="top">I like the idea and the lighting, but this looks quite a bit overprocessed, it reminds me of "digital art" rather than a photo.</td>', 'I like the idea and the lighting, but this looks quite a bit overprocessed, it reminds me of "digital art" rather than a photo.', '2003-12-15 09:23:53.000000', NULL, 1),
(513585, 50724, 10686, '<td valign="top">I like the effect, but there is just too much negative space</td>', 'I like the effect, but there is just too much negative space', '2003-12-15 09:25:50.000000', NULL, 1),
(513587, 50737, 10686, '<td valign="top">I like this, but I''m not so sure about the background color.</td>', 'I like this, but I''m not so sure about the background color.', '2003-12-15 09:31:06.000000', NULL, 1),
