(513678, 50860, 7703, '<td valign="top">The border are to much.</td>', 'The border are to much.', '2003-12-15 11:04:16.000000', NULL, 1),
(513679, 50561, 10084, '<td valign="top">Very crisp and sharp focusing. Composition is pleasing to the eye. Incredible highlights in the water and the glass. The orange subject helps to give the viewer some focus in the piece. The black background frames the subject very well and helps to make the central subject pop out.Absolutely beautiful.</td>', 'Very crisp and sharp focusing. Composition is pleasing to the eye. Incredible highlights in the water and the glass. The orange subject helps to give the viewer some focus in the piece. The black background frames the subject very well and helps to make the central subject pop out.Absolutely beautiful.', '2003-12-15 11:04:19.000000', NULL, 1),
(513680, 50743, 10084, '<td valign="top">Great depth of field in the picture. The circular object is pleasing to the eye. The waters'' reflective highlights are very crisp and sharp.<br/>The only thing I would change is to maybe do a little cloning of the background.</td>', 'Great depth of field in the picture. The circular object is pleasing to the eye. The waters'' reflective highlights are very crisp and sharp.The only thing I would change is to maybe do a little cloning of the background.', '2003-12-15 11:07:09.000000', NULL, 1),
(513683, 50520, 10084, '<td valign="top">Beautiful blue hues in the picture. Composition is definitely interesting. The droplet of water has perfect focus. Love the crisp highlight on the droplet.</td>', 'Beautiful blue hues in the picture. Composition is definitely interesting. The droplet of water has perfect focus. Love the crisp highlight on the droplet.', '2003-12-15 11:11:52.000000', NULL, 1),
