(514458, 50816, 3724, '<td valign="top">Soft unusuall pastel colour combinations in this scene are attractive and the balance of the design is keeping me off center which i like - here is an interesting and pleasing abstract with unknown presumably sky reflections on the active - but muted liquid,  surrounded by the engaging sharper focus.</td>', 'Soft unusuall pastel colour combinations in this scene are attractive and the balance of the design is keeping me off center which i like - here is an interesting and pleasing abstract with unknown presumably sky reflections on the active - but muted liquid,  surrounded by the engaging sharper focus.', '2003-12-16 11:12:14.000000', NULL, 1),
(514466, 50880, 3724, '<td valign="top">Title is appropriate,  it is a minimal beauty and with simple yet intricate elements.  I like it.</td>', 'Title is appropriate,  it is a minimal beauty and with simple yet intricate elements.  I like it.', '2003-12-16 11:26:13.000000', NULL, 1),
(514498, 50048, 14715, '<td valign="top">I feel like the dark edge on the left pulls away a bit from the image.  Crop perhaps.  Great image and high score from me.</td>', 'I feel like the dark edge on the left pulls away a bit from the image.  Crop perhaps.  Great image and high score from me.', '2003-12-16 12:40:31.000000', NULL, 1),
