INSERT INTO comments ("id", "image_id", "commenter_id", "raw_comment", "comment", "date", "edited", "made_during_challenge") VALUES
(516853, 50841, 7291, '<td valign="top">Very nice.  I feel it''s a little to focused on the left.  Panning to the right a little bit showing less grass and more water might give a different effect with more emphasis on the water.  Great picture none the less.</td>', 'Very nice.  I feel it''s a little to focused on the left.  Panning to the right a little bit showing less grass and more water might give a different effect with more emphasis on the water.  Great picture none the less.', '2003-12-18 13:03:54.000000', NULL, 1),
(516855, 50795, 7291, '<td valign="top">It appears as if this picture might have lacked some color and the saturation was pushed up to help it.  It might have been pushed too much though because there is a ton of noise that is very distracting.</td>', 'It appears as if this picture might have lacked some color and the saturation was pushed up to help it.  It might have been pushed too much though because there is a ton of noise that is very distracting.', '2003-12-18 13:07:10.000000', NULL, 1),
(516858, 50660, 7291, '<td valign="top">Excellent color and use of reflection to fill some negative space.</td>', 'Excellent color and use of reflection to fill some negative space.', '2003-12-18 13:09:01.000000', NULL, 1),
