(518357, 50841, 12611, '<td valign="top">Fantastic orange color. The water is a bit washed out.</td>', 'Fantastic orange color. The water is a bit washed out.', '2003-12-20 10:24:04.000000', NULL, 1),
(518358, 50042, 12611, '<td valign="top">The title is a bit much- THe grapes are nice though.</td>', 'The title is a bit much- THe grapes are nice though.', '2003-12-20 10:27:21.000000', NULL, 1),
(518359, 50746, 12611, '<td valign="top">Awesome shot.</td>', 'Awesome shot.', '2003-12-20 10:29:09.000000', NULL, 1),
(518360, 50048, 12611, '<td valign="top">Great shot here. You are a master of photgraphing liquid. I love the ripples. THe composition and cropping are the only detractors to this awesome shot.</td>', 'Great shot here. You are a master of photgraphing liquid. I love the ripples. THe composition and cropping are the only detractors to this awesome shot.', '2003-12-20 10:30:52.000000', NULL, 1),
(518361, 50135, 12611, '<td valign="top">Good shot- good cropping. It is refeshing to see a person in a shot rather than a water droplet in a studio.</td>', 'Good shot- good cropping. It is refeshing to see a person in a shot rather than a water droplet in a studio.', '2003-12-20 10:32:02.000000', NULL, 1),
(518362, 50724, 12611, '<td valign="top">Fantastically artsy. I love it- others may say it is a bit unnatural looking- but I prefer to say that  it is supernatural looking.</td>', 'Fantastically artsy. I love it- others may say it is a bit unnatural looking- but I prefer to say that  it is supernatural looking.', '2003-12-20 10:33:15.000000', NULL, 1),
