(518685, 50905, 6870, '<td valign="top">Very simple shot. DoF works well here. water sphere is sharp. Engaging, interesting photo!</td>', 'Very simple shot. DoF works well here. water sphere is sharp. Engaging, interesting photo!', '2003-12-20 19:49:55.000000', NULL, 1),
(518687, 50833, 6870, '<td valign="top">Looks nice and chilly! Overall clarity is very nice.</td>', 'Looks nice and chilly! Overall clarity is very nice.', '2003-12-20 19:50:57.000000', NULL, 1),
(518688, 50574, 6870, '<td valign="top">Doh! Strong composition, and good use of negative space! It looks like he''s sitting in milk--ah, but there are the bubbles. Fun shot.</td>', 'Doh! Strong composition, and good use of negative space! It looks like he''s sitting in milk--ah, but there are the bubbles. Fun shot.', '2003-12-20 19:52:24.000000', NULL, 1),
