(518690, 50878, 6870, '<td valign="top">Interesting patterns. The blue candle is well positioned in the frame. The clarity suffers here a little, but I still like the shot.</td>', 'Interesting patterns. The blue candle is well positioned in the frame. The clarity suffers here a little, but I still like the shot.', '2003-12-20 19:54:40.000000', NULL, 1),
(518692, 50894, 6870, '<td valign="top">This looks like a drink from Star Trek! Fun colors and dramatic lighting. INteresting mood evoked.</td>', 'This looks like a drink from Star Trek! Fun colors and dramatic lighting. INteresting mood evoked.', '2003-12-20 19:55:24.000000', NULL, 1),
(518693, 50896, 6870, '<td valign="top">The image lacks some clarity,but the S curve works so nicely here, and the colors and tones are really marvelous.</td>', 'The image lacks some clarity,but the S curve works so nicely here, and the colors and tones are really marvelous.', '2003-12-20 19:55:59.000000', NULL, 1),
