(518907, 50087, 2780, '<td valign="top">I really like these long exposure shots, the uniformity to this composition works very well. 7</td>', 'I really like these long exposure shots, the uniformity to this composition works very well. 7', '2003-12-21 09:03:59.000000', NULL, 1),
