(519429, 50832, 3102, '<td valign="top">Beautiful -- I love the reflection!</td>', 'Beautiful -- I love the reflection!', '2003-12-21 23:58:10.000000', NULL, 1),
(519430, 50775, 10084, '<td valign="top">Beautiful composition. The shot is crisp and crystal clear. Love the diagonal composition really helps to make the image pop out. The reflections and highlights in the droplets are incredible.</td>', 'Beautiful composition. The shot is crisp and crystal clear. Love the diagonal composition really helps to make the image pop out. The reflections and highlights in the droplets are incredible.', '2003-12-21 23:58:17.000000', NULL, 1),
(519432, 50400, 3102, '<td valign="top">I like the tone of this a lot -- very nice and sharp, and interesting.</td>', 'I like the tone of this a lot -- very nice and sharp, and interesting.', '2003-12-21 23:58:55.000000', NULL, 1),
(519436, 50660, 2333, '<td valign="top">Ahhh, JJ you''ve done yet again! Congrats! this was my fav.</td>', 'Ahhh, JJ you''ve done yet again! Congrats! this was my fav.', '2003-12-22 00:00:52.000000', NULL, 0),
(519437, 50660, 3102, '<td valign="top">Awesome!  Congrats on the ribbon, yet again -- well deserved!</td>', 'Awesome!  Congrats on the ribbon, yet again -- well deserved!', '2003-12-22 00:02:01.000000', NULL, 0),
(519439, 50660, 10084, '<td valign="top">Another incredible photo. Congratulations.</td>', 'Another incredible photo. Congratulations.', '2003-12-22 00:02:40.000000', NULL, 0),
(519440, 50660, 7969, '<td valign="top">Again!! Another fab photo!</td>', 'Again!! Another fab photo!', '2003-12-22 00:03:27.000000', NULL, 0),
(519441, 50872, 10084, '<td valign="top">Congratulations. Definitely joining the best photographers in Iceland.</td>', 'Congratulations. Definitely joining the best photographers in Iceland.', '2003-12-22 00:03:45.000000', NULL, 0),
(519442, 50660, 12268, '<td valign="top">JJ, Dude! Do you ever get tried of winning SO MANY damn ribbons?! :) It''s hard work being SOOOO GOOD! Congrat on another great shot &amp; blue ribbon! <br/> <br/>Oh, yeah, I could really use a mentor!</td>', 'JJ, Dude! Do you ever get tried of winning SO MANY damn ribbons?! :) It''s hard work being SOOOO GOOD! Congrat on another great shot & blue ribbon!  Oh, yeah, I could really use a mentor!', '2003-12-22 00:03:47.000000', NULL, 0),
