(519449, 50660, 1717, '<td valign="top">absolutely stunning, jj, and my favorite of the challenge...congratulations!</td>', 'absolutely stunning, jj, and my favorite of the challenge...congratulations!', '2003-12-22 00:07:10.000000', NULL, 0),
(519452, 50520, 10084, '<td valign="top">I thought this one would definitely have received a higher place.<br/><br/><i>Message edited by author 2003-12-22 00:09:00.</i></td>', 'I thought this one would definitely have received a higher place.', '2003-12-22 00:08:46.000000', '2003-12-22 00:09:00.000000', 0),
