(519458, 50400, 9906, '<td valign="top">I thought for sure that this was a winner....Nice work John!<br/>TC</td>', 'I thought for sure that this was a winner....Nice work John!TC', '2003-12-22 00:10:53.000000', NULL, 0),
(519460, 50852, 327, '<td valign="top">Congrats!!</td>', 'Congrats!!', '2003-12-22 00:11:18.000000', NULL, 0),
(519463, 50870, 2752, '<td valign="top">I really thought this would rate higher..great composition and use of colors.</td>', 'I really thought this would rate higher..great composition and use of colors.', '2003-12-22 00:12:16.000000', NULL, 0),
(519464, 50598, 10084, '<td valign="top">I was hoping you would get a much higher placing.Simply an amazing shot. So unique, maybe it was too unique for some people.Maybe they thought you used a filter. Definitely would''ve receive a higher score if Dec rules were not in effect. Wonderful shot.</td>', 'I was hoping you would get a much higher placing.Simply an amazing shot. So unique, maybe it was too unique for some people.Maybe they thought you used a filter. Definitely would''ve receive a higher score if Dec rules were not in effect. Wonderful shot.', '2003-12-22 00:12:48.000000', NULL, 0),
(519473, 50660, 10437, '<td valign="top">A true masterpiece!<br/>Félicitations,JJ</td>', 'A true masterpiece!Félicitations,JJ', '2003-12-22 00:15:25.000000', NULL, 0);
INSERT INTO comments ("id", "image_id", "commenter_id", "raw_comment", "comment", "date", "edited", "made_during_challenge") VALUES
(519478, 50872, 13091, '<td valign="top">Coooool one Oskar!!! Congrats on your first ribbon.</td>', 'Coooool one Oskar!!! Congrats on your first ribbon.', '2003-12-22 00:18:30.000000', NULL, 0),
(519483, 50870, 2567, '<td valign="top">Thanks for the comments everyone.</td>', 'Thanks for the comments everyone.', '2003-12-22 00:21:33.000000', NULL, 0),
(519485, 50872, 12268, '<td valign="top">Congrats on your first ribbon! I can;t believe you got a 2! Well deserved ribbon! Coming in second to JJ is like coming in first!</td>', 'Congrats on your first ribbon! I can;t believe you got a 2! Well deserved ribbon! Coming in second to JJ is like coming in first!', '2003-12-22 00:22:30.000000', NULL, 0),
(519536, 50892, 10702, '<td valign="top">5 people giving you a three ! I didn''t belive it was the real thing until you described how you did it, awesome shot !</td>', '5 people giving you a three ! I didn''t belive it was the real thing until you described how you did it, awesome shot !', '2003-12-22 00:53:46.000000', NULL, 0),
(519539, 50852, 11078, '<td valign="top">I didnt see this when the voting was on. But I love it!<br/> <br/>Iris ''s are my favorite. beautiful work Well done! love the colour</td>', 'I didnt see this when the voting was on. But I love it! Iris ''s are my favorite. beautiful work Well done! love the colour', '2003-12-22 00:56:26.000000', NULL, 0),
(519546, 50660, 6388, '<td valign="top">some day you may cease to amaze me JJ.  i have no idea when that might be though.<br/> <br/>Pedro</td>', 'some day you may cease to amaze me JJ.  i have no idea when that might be though. Pedro', '2003-12-22 01:09:24.000000', NULL, 0),
(519548, 50660, 4159, '<td valign="top">This is art.  Congratulations.</td>', 'This is art.  Congratulations.', '2003-12-22 01:18:24.000000', NULL, 0),
(519551, 50852, 10437, '<td valign="top">Amazingly beautiful, congratulations for your first ribbon</td>', 'Amazingly beautiful, congratulations for your first ribbon', '2003-12-22 01:28:15.000000', NULL, 0),
(519558, 50069, 9073, '<td valign="top">In your comments, you say that getting a nice, sharp, even focus was difficult. I think that the reason for this was that you used f2.0, one of the widest stops possible. <br/> <br/>If you had used a narrower stop, like f5.6 or so, more of the shot would have been in clearer focus. What I do when I absolutely need the shot to be in focus is to use my narrowest stop (f9.5). But experience tells me that for a 5-10 cm object f5.6 is enough. You need to experiment.</td>', 'In your comments, you say that getting a nice, sharp, even focus was difficult. I think that the reason for this was that you used f2.0, one of the widest stops possible.  If you had used a narrower stop, like f5.6 or so, more of the shot would have been in clearer focus. What I do when I absolutely need the shot to be in focus is to use my narrowest stop (f9.5). But experience tells me that for a 5-10 cm object f5.6 is enough. You need to experiment.', '2003-12-22 02:12:20.000000', NULL, 0),
(519586, 50872, 7703, '<td valign="top">Til hamingju. Ég er samt að velt fyrir mér hverjum datt í hug að gefa þér 2 í einkunn? Þú fékkst allavega 10 frá mér, enda er þetta mjög vel tekin mynd. <br/>Halltu þessu áfram :)</td>', 'Til hamingju. Ég er samt að velt fyrir mér hverjum datt í hug að gefa þér 2 í einkunn? Þú fékkst allavega 10 frá mér, enda er þetta mjög vel tekin mynd. Halltu þessu áfram :)', '2003-12-22 04:02:57.000000', NULL, 0),
(519599, 50872, 4400, '<td valign="top">Já það gat ekki annað verið, þetta er mögnuð mynd til hamingju glæsilegt!!</td>', 'Já það gat ekki annað verið, þetta er mögnuð mynd til hamingju glæsilegt!!', '2003-12-22 04:32:26.000000', NULL, 0),
(519621, 50660, 10702, '<td valign="top">Really nice shot. That was one of my favorites in this challenge, well deserved first place.<br/> <br/>I was kind of hoping to get the blue one, but I don''t mind losing to a masterpiece like this one.</td>', 'Really nice shot. That was one of my favorites in this challenge, well deserved first place. I was kind of hoping to get the blue one, but I don''t mind losing to a masterpiece like this one.', '2003-12-22 05:30:49.000000', NULL, 0),
